"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6664],{24147:e=>{e.exports=JSON.parse('{"functions":[{"name":"Init","desc":"Scans `workspace.SpawnVolumes` and rebuilds the internal weighted cache\\nfrom all `BasePart` children.  Must be called at least once before\\n`GetRandomPoint`.  Safe to call again if spawn volumes change at runtime.","params":[],"returns":[],"function_type":"method","source":{"line":55,"path":"src/ReplicatedStorage/SharedModules/SpawnHelper.luau"}},{"name":"GetRandomPoint","desc":"Returns a uniformly random `Vector3` point inside one of the registered\\nspawn volumes.  Volume selection is weighted by world-space volume so\\nlarger parts are proportionally more likely to be chosen.\\n\\nReturns `nil` if `Init` has not been called or no volumes are registered.","params":[],"returns":[{"desc":"A random world-space position, or `nil`.","lua_type":"Vector3?"}],"function_type":"static","source":{"line":79,"path":"src/ReplicatedStorage/SharedModules/SpawnHelper.luau"}}],"properties":[],"types":[],"name":"SpawnHelper","desc":"Utility for volume-weighted random spawn point selection.\\n\\nOn startup the module locates (or creates) a `Folder` named\\n`SpawnVolumes` in `workspace`.  Each `BasePart` child of that folder is\\ntreated as a spawn volume; its weight is proportional to its world-space\\nvolume (`Size.X * Size.Y * Size.Z`).\\n\\n`Init` must be called before `GetRandomPoint` to populate the internal\\nweighted cache.\\n\\n```lua\\nlocal SpawnHelper = require(path.to.SpawnHelper)\\n\\nSpawnHelper:Init()\\nlocal point = SpawnHelper.GetRandomPoint()\\nif point then\\n\\tcharacter:PivotTo(CFrame.new(point))\\nend\\n```","source":{"line":28,"path":"src/ReplicatedStorage/SharedModules/SpawnHelper.luau"}}')}}]);